file.content:
.standup-overlay {
  position: fixed; inset: 0;
  /* Overlay blurs the board; modal sits transparently on top */
  background: rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(10px) saturate(160%) brightness(0.82);
  -webkit-backdrop-filter: blur(10px) saturate(160%) brightness(0.82);
  z-index: 400; display: flex; align-items: center; justify-content: center; padding: 20px;
}
.standup-modal {
  background: rgba(16, 18, 44, 0.18);
  backdrop-filter: none;
  border: 1.5px solid rgba(255,255,255,0.12);
  border-radius: 14px;
  width: 580px; max-width: 100%; max-height: 80vh; display: flex; flex-direction: column;
  animation: fadeScaleIn 0.18s ease;
  box-shadow: 0 32px 80px rgba(0,0,0,0.40), inset 0 1.5px 0 rgba(255,255,255,0.14);
}
.standup-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px; border-bottom: 1px solid #2a2a3d;
}
.standup-title { font-size: 13px; font-weight: 600; color: #cdd6f4; display: flex; align-items: center; gap: 8px; }
.standup-title svg { color: #89b4fa; }
.standup-body { flex: 1; overflow-y: auto; padding: 16px; }
.standup-md {
  font-size: 12px; color: #cdd6f4; white-space: pre-wrap; line-height: 1.7;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.standup-footer {
  display: flex; align-items: center; justify-content: flex-end;
  gap: 8px; padding: 12px 16px; border-top: 1px solid #2a2a3d;
}

/* View toggle pill */
.standup-view-toggle {
  display: flex;
  border: 1px solid #2a2a3d;
  border-radius: 6px;
  overflow: hidden;
  flex-shrink: 0;
}
.standup-view-btn {
  display: inline-flex;
  align-items: center;
  line-height: 1;
  padding: 5px 12px;
  font-size: 11px;
  font-weight: 500;
  background: transparent;
  border: none;
  color: #585b70;
  cursor: pointer;
  transition: all 0.15s;
  height: 28px;
}
.standup-view-btn:not(:last-child) { border-right: 1px solid #2a2a3d; }
.standup-view-btn.active { background: #89b4fa22; color: #89b4fa; }
.standup-view-btn:hover:not(.active) { background: #1e1e2d; color: #cdd6f4; }

/* Rendered markdown styles */
.standup-rendered { line-height: 1.65; }
.standup-h2 {
  font-size: 14px; font-weight: 700; color: #cdd6f4;
  margin: 0 0 12px; padding-bottom: 8px; border-bottom: 1px solid #2a2a3d;
}
.standup-h3 {
  font-size: 12px; font-weight: 600; color: #a6adc8;
  margin: 12px 0 6px;
}
.standup-li {
  display: flex; gap: 8px; align-items: baseline;
  font-size: 12px; color: #cdd6f4; margin-bottom: 4px;
}
.standup-bullet { color: #585b70; flex-shrink: 0; font-size: 14px; line-height: 1.3; }
.standup-p { font-size: 12px; color: #6c7086; margin: 6px 0; }
.standup-em { color: #6c7086; font-style: italic; }
.standup-link {
  color: #89b4fa; text-decoration: none; font-weight: 500;
}
.standup-link:hover { text-decoration: underline; }
.standup-spacer { height: 10px; }

/* ── Standup rich view ───────────────────────── */
.su-date {
  font-size: 11px; color: #6c7086; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.5px;
  margin-bottom: 14px;
}
.su-section { margin-bottom: 16px; }
.su-section-header {
  display: flex; align-items: center; gap: 7px;
  margin-bottom: 6px;
}
.su-section-icon { font-size: 13px; line-height: 1; flex-shrink: 0; }
.su-section-title {
  font-size: 13px; font-weight: 700; color: #cdd6f4; flex: 1;
}
.su-section-count {
  font-size: 11px; color: #6c7086; background: #1e1e2d;
  border-radius: 8px; padding: 1px 7px; font-weight: 600;
}
.su-repo-group { margin-left: 4px; margin-bottom: 4px; }
.su-repo-header {
  display: flex; align-items: center; gap: 6px;
  background: none; border: none; color: #a6adc8;
  cursor: pointer; padding: 3px 4px; border-radius: 5px;
  font-size: 12px; font-weight: 600; width: 100%; text-align: left;
  transition: background 0.1s;
}
.su-repo-header:hover { background: #1e1e2d; color: #cdd6f4; }
.su-repo-chevron {
  transition: transform 0.15s; flex-shrink: 0; color: #585b70;
  transform: rotate(0deg);
}
.su-repo-chevron.open { transform: rotate(90deg); }
.su-repo-name { flex: 1; }
.su-repo-count {
  font-size: 10px; color: #6c7086; background: #181826;
  border-radius: 6px; padding: 1px 6px;
}
.su-repo-items {
  display: flex; flex-direction: column; gap: 1px;
  margin-left: 20px; padding-left: 8px;
  border-left: 1px solid #2a2a3d; margin-bottom: 4px;
}
.su-item {
  display: flex; align-items: center; gap: 6px;
  background: none; border: none; color: #cdd6f4;
  cursor: pointer; padding: 3px 6px; border-radius: 5px;
  font-size: 12px; text-align: left; width: 100%;
  transition: background 0.1s;
}
.su-item:hover { background: #1e1e2d; }
.su-item-num { color: #585b70; font-size: 11px; flex-shrink: 0; }
.su-item-title { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

